import React, { useState } from "react";
import * as XLSX from "xlsx";
import {
  Box,
  Container,
  Typography,
  Paper,
  Input,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Card,
  CardContent,
  LinearProgress,
  Tooltip,
} from "@mui/material";
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, Legend, LabelList } from "recharts";

interface Job {
  [key: string]: any;
}

interface InstallerStats {
  installer: string;
  totalJobs: number;
  customerSatisfactionJobs: number;
  jobs: Job[];
}

const parseJobs = (sheet: XLSX.WorkSheet): Job[] => {
  const rows: any[][] = XLSX.utils.sheet_to_json(sheet, { header: 1 });
  if (rows.length < 2) return [];
  const jobs: Job[] = [];
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const job: Job = {};
    // Store columns from A to K (0-10)
    for (let col = 0; col <= 10; col++) {
      job[String.fromCharCode("A".charCodeAt(0) + col)] = row[col] ?? "";
    }
    jobs.push(job);
  }
  return jobs;
};

const getInstallersStats = (jobs: Job[]): InstallerStats[] => {
  const installerMap: Record<string, InstallerStats> = {};
  jobs.forEach((job) => {
    const installer = job["C"] || "Unknown";
    if (!installerMap[installer]) {
      installerMap[installer] = {
        installer,
        totalJobs: 0,
        customerSatisfactionJobs: 0,
        jobs: [],
      };
    }
    installerMap[installer].totalJobs += 1;
    installerMap[installer].jobs.push(job);
    if (
      typeof job["F"] === "string" &&
      job["F"].toLowerCase().includes("customer satisfaction")
    ) {
      installerMap[installer].customerSatisfactionJobs += 1;
    }
  });
  return Object.values(installerMap);
};

const getProblemChild = (stats: InstallerStats[]): InstallerStats | null => {
  if (!stats.length) return null;
  // Sort by customerSatisfactionJobs descending, then totalJobs descending
  return stats
    .slice()
    .sort(
      (a, b) =>
        b.customerSatisfactionJobs - a.customerSatisfactionJobs ||
        b.totalJobs - a.totalJobs
    )[0];
};

const columns = [
  "A","B","C","D","E","F","G","H","I","J","K"
];

// Helper for chart colors
const chartColors = [
  "#f87171", "#fbbf24", "#34d399", "#60a5fa", "#a78bfa", "#f472b6", "#38bdf8", "#fcd34d", "#c084fc", "#facc15"
];

const App: React.FC = () => {
  const [jobs, setJobs] = useState<Job[]>([]);
  const [installerStats, setInstallerStats] = useState<InstallerStats[]>([]);
  const [problemChild, setProblemChild] = useState<InstallerStats | null>(null);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const data = evt.target?.result;
      if (typeof data !== "string" && !(data instanceof ArrayBuffer)) return;
      const workbook = XLSX.read(data, { type: "binary" });
      const firstSheetName = workbook.SheetNames[0];
      const sheet = workbook.Sheets[firstSheetName];
      const parsedJobs = parseJobs(sheet);
      setJobs(parsedJobs);

      const stats = getInstallersStats(parsedJobs);
      setInstallerStats(stats);
      setProblemChild(getProblemChild(stats));
    };
    reader.readAsBinaryString(file);
  };

  // For chart data: each installer, with total jobs and customer satisfaction jobs
  const chartData = installerStats.map((stat, idx) => ({
    name: stat.installer,
    "Jobs": stat.totalJobs,
    "Customer Satisfaction": stat.customerSatisfactionJobs,
    color: chartColors[idx % chartColors.length],
  }));

  return (
    <Box sx={{ bgcolor: "#f8fafc", minHeight: "100vh", py: 6 }}>
      <Container maxWidth="lg">
        <Paper elevation={4} sx={{ p: 4, borderRadius: 3, mb: 5 }}>
          <Typography variant="h3" fontWeight={700} gutterBottom color="primary">
            Problem Child Installer Analyzer
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>
            Upload your <b>.xlsx</b> file to analyze which installer is having the most customer satisfaction issues. Get a clear view of who needs help and which jobs are affected.
          </Typography>
          <Input
            type="file"
            inputProps={{ accept: ".xlsx, .xls" }}
            onChange={handleFile}
            sx={{ my: 2 }}
          />
        </Paper>

        {installerStats.length > 0 && (
          <>
            <Box sx={{ display: "flex", gap: 3, flexWrap: "wrap", mb: 5 }}>
              <Card sx={{ minWidth: 320, bgcolor: "#f5f5f5" }}>
                <CardContent>
                  <Typography variant="h5" gutterBottom color="error" fontWeight={700}>
                    Problem Child
                  </Typography>
                  {problemChild ? (
                    <>
                      <Typography variant="h6">
                        <span style={{ fontWeight: 600 }}>{problemChild.installer}</span>
                      </Typography>
                      <Typography sx={{ mt: 1 }}>
                        Total Jobs: <b>{problemChild.totalJobs}</b>
                      </Typography>
                      <Typography>
                        Jobs Marked "Customer Satisfaction": <b style={{ color: "#d32f2f" }}>{problemChild.customerSatisfactionJobs}</b>
                      </Typography>
                      <Box sx={{ mt: 3 }}>
                        <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>
                          Percentage of Problem Jobs
                        </Typography>
                        <Tooltip title={`${((problemChild.customerSatisfactionJobs/problemChild.totalJobs)*100).toFixed(1)}%`}>
                          <LinearProgress
                            variant="determinate"
                            value={problemChild.totalJobs ? (problemChild.customerSatisfactionJobs/problemChild.totalJobs)*100 : 0}
                            sx={{
                              height: 12,
                              borderRadius: 6,
                              backgroundColor: "#e0e0e0",
                              "& .MuiLinearProgress-bar": {
                                backgroundColor: "#d32f2f",
                              },
                            }}
                          />
                        </Tooltip>
                      </Box>
                    </>
                  ) : (
                    <Typography>No data found.</Typography>
                  )}
                </CardContent>
              </Card>

              <Card sx={{ flex: 1, minWidth: 300, bgcolor: "#f5f5f5" }}>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    Installer Comparison
                  </Typography>
                  <Box sx={{ height: 280 }}>
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData} margin={{ top: 20, right: 20, left: 0, bottom: 30 }}>
                        <XAxis dataKey="name" angle={-20} textAnchor="end" height={60} interval={0} />
                        <YAxis allowDecimals={false} />
                        <RechartsTooltip />
                        <Legend verticalAlign="top" />
                        <Bar dataKey="Jobs" fill="#1976d2" radius={[8,8,0,0]} >
                          <LabelList dataKey="Jobs" position="top" />
                        </Bar>
                        <Bar dataKey="Customer Satisfaction" fill="#d32f2f" radius={[8,8,0,0]}>
                          <LabelList dataKey="Customer Satisfaction" position="top" />
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </Box>
                  <Typography variant="caption" color="text.secondary">
                    <span style={{ color: "#1976d2", fontWeight: 700 }}>Blue</span> = Total Jobs,&nbsp;
                    <span style={{ color: "#d32f2f", fontWeight: 700 }}>Red</span> = Jobs with "Customer Satisfaction"
                  </Typography>
                </CardContent>
              </Card>
            </Box>

            {problemChild && (
              <Paper elevation={3} sx={{ mb: 5, p: 3, borderRadius: 2 }}>
                <Typography variant="h6" color="error" fontWeight={600} sx={{ mb: 2 }}>
                  Jobs with "Customer Satisfaction" for {problemChild.installer}
                </Typography>
                {problemChild.jobs.filter(j =>
                  typeof j["F"] === "string" && j["F"].toLowerCase().includes("customer satisfaction")
                ).length > 0 ? (
                  <TableContainer sx={{ borderRadius: 2 }}>
                    <Table size="small">
                      <TableHead sx={{ bgcolor: "#f7eaea" }}>
                        <TableRow>
                          {columns.map((col) => (
                            <TableCell key={col}><b>{col}</b></TableCell>
                          ))}
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {problemChild.jobs
                          .filter(j =>
                            typeof j["F"] === "string" && j["F"].toLowerCase().includes("customer satisfaction")
                          )
                          .map((job, idx) => (
                            <TableRow key={idx}>
                              {columns.map((col) => (
                                <TableCell key={col}>{job[col]}</TableCell>
                              ))}
                            </TableRow>
                          ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                ) : (
                  <Typography color="text.secondary">None found for this installer.</Typography>
                )}
              </Paper>
            )}

            <Paper elevation={1} sx={{ p: 3, borderRadius: 2 }}>
              <Typography variant="h6" fontWeight={600} sx={{ mb: 2 }}>
                All Jobs List
              </Typography>
              <TableContainer sx={{ borderRadius: 2 }}>
                <Table size="small">
                  <TableHead sx={{ bgcolor: "#e3e3e3" }}>
                    <TableRow>
                      {columns.map((col) => (
                        <TableCell key={col}><b>{col}</b></TableCell>
                      ))}
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {jobs.map((job, idx) => (
                      <TableRow key={idx}>
                        {columns.map((col) => (
                          <TableCell key={col}>{job[col]}</TableCell>
                        ))}
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          </>
        )}

        {!installerStats.length && (
          <Paper sx={{ mt: 6, p: 4, color: "#888", textAlign: "center" }}>
            <Typography variant="h6" color="text.secondary">
              Please upload an .xlsx file to get started.
            </Typography>
          </Paper>
        )}

        <Box sx={{ mt: 8, mb: 2, textAlign: "center", color: "#bbb" }}>
          <Typography variant="caption">
            &copy; {new Date().getFullYear()} Problem Child Analyzer for Installers
          </Typography>
        </Box>
      </Container>
    </Box>
  );
};

export default App;